import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.ts";

const col = (m: ArrayLike<number>, c: number) => [m[c * 4]!, m[c * 4 + 1]!, m[c * 4 + 2]!];
const near = (a: number[], b: number[], eps = 1e-9) => a.forEach((v, i) => expect(Math.abs(v - b[i]!)).toBeLessThan(eps));
const n = (v: number[]) => { const l = Math.hypot(...v); return v.map((x) => x / l); };

describe("chase camera", () => {
    it("starts upright and looks at target", () => {
        const cc = createChaseCamera({ x: 0, y: 2, z: -10 }, { x: 0, y: 0, z: 0 });
        const m = cc.camera.worldMatrix;
        near(col(m, 1), n([0, 10, 2]).map((_, i) => [0, 10, 2][i] ? 0 : 0).map((_, i) => (i === 1 ? 0 : 0)).length ? n([0, 10, 2]) : []);
        near(col(m, 2), n([0, -2, 10]));
        near(col(m, 3), [0, 2, -10]);
    });

    it("rolls so screen-up is the projection of the requested up", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        cc.bank({ x: 1, y: 1, z: 0 });
        near(col(cc.camera.worldMatrix, 2), [0, 0, 1]);
        near(col(cc.camera.worldMatrix, 1), n([1, 1, 0]));
        cc.bank({ x: 0, y: 1, z: 1 });
        // view dir d=(0,0,1); proj of (0,1,1) onto plane perp to d is (0,1,0)
        near(col(cc.camera.worldMatrix, 1), [0, 1, 0]);
    });

    it("keeps looking at target and previous roll for up along line of sight, both ways", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        cc.bank({ x: 1, y: 0, z: 0 });
        const before = Array.from(cc.camera.worldMatrix);
        cc.bank({ x: 0, y: 0, z: 1 });
        near(Array.from(cc.camera.worldMatrix), before);
        cc.bank({ x: 0, y: 0, z: -1 });
        near(Array.from(cc.camera.worldMatrix), before);
        near(col(cc.camera.worldMatrix, 2), [0, 0, 1]);
    });

    it("keeps previous roll when the view moved and the new up is along the new line of sight", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        cc.bank({ x: 1, y: 0, z: 0 });
        cc.camera.target.set(1, 0, 0);
        const d = n([1, 0, 10]);
        cc.bank(d as any);
        const y = col(cc.camera.worldMatrix, 1);
        near(col(cc.camera.worldMatrix, 2), d);
        // previous screen-up was +X; projection onto new plane
        const dot = d[0]!;
        near(y, n([1 - dot * d[0]!, 0, 0 - dot * d[2]!]));
    });

    it("does not hit identity fallback for near-parallel up", () => {
        const cc = createChaseCamera({ x: 0, y: 0, z: -10 }, { x: 0, y: 0, z: 0 });
        cc.bank({ x: 0, y: 1, z: 0 });
        cc.bank({ x: 1e-12, y: 0, z: 1 });
        near(col(cc.camera.worldMatrix, 2), [0, 0, 1]);
        near(col(cc.camera.worldMatrix, 1), [0, 1, 0], 1e-6);
    });
});
